#include <cassert>
#include <iostream>

int numero_visita{0};

int registrar_visita() {
    ++numero_visita;
    return numero_visita;
}

int main() {
    assert(registrar_visita() > 0);
    std::cout << "Visits=" << numero_visita << "\n";
    return 0;
}

const int primera = registrar_visita();
assert(primera > 0);
std::cout << "Visits=" << numero_visita << ";First=" << primera << "\n";
